import re
from typing import List, Tuple

def calculate(text: str) -> int:
    def reduce(values: List[int]) -> int:
        sum = 0
        sign = 1
        for value in values:
            sum += sign * value
            sign = -sign
        return sum

    def parse(text: str) -> int:
        factorial_pattern = r'(\d+)(?=\*|\+| |\))'
        factors = [int(factor) for factor in re.findall(factorial_pattern, text)]
        if len(factors) == 0:
            return 0
        value = reduce(factors)
        text = re.sub(factorial_pattern, str(value), text, count=1)
        return int(parse_recursive(text))

    def parse_recursive(text: str) -> str:
        if '(' in text:
            start = text.rfind('(')
            end = start + 1
            depth = 1
            while depth > 0:
                end += 1
                if text[end] == '(':
                    depth += 1
                elif text[end] == ')':
                    depth -= 1
            subtext = text[start+1:end]
            value = parse(subtext)
            new_text = text[:start] + str(value) + text[end+1:]
            _, result = parse_pratt(new_text)
            return result
        else:
            return text

    def parse_pratt(text: str) -> Tuple[List[int], str]:
        unparse_token = ['*', '+', ')']
        values = []
        operations = []
        tokens = re.findall(r'\d+|\*|\+|\(|\)', text)
        for token in tokens:
            if token.isdigit():
                values.append(int(token))
            elif token == '(':
                operations.append(token)
            elif token == ')':
                while operations[-1]!= '(':
                    values.append(operations.pop())
                operations.pop()
            else:
                while operations and operations[-1]!= '(' and unparse_token.index(token) >= unparse_token.index(operations[-1]):
                    values.append(operations.pop())
                operations.append(token)
        while operations:
            values.append(operations.pop())
        result = calculate_pratt(values, operations)
        return [], result

    def calculate_pratt(values: List[int], operations: List[str]) -> int:
        stack = []
        for value in values:
            stack.append(value)
        for operation in operations:
            b = stack.pop()
            a = stack.pop()
            if operation == '*':
                stack.append(a*b)
            elif operation == '+':
                stack.append(a+b)
        return stack[0]

    return parse(text)

def main():
    inputs = []
    while True:
        try:
            length, expression = input().split()
            length = int(length)
            if length == 0:
                break
            inputs.append((length, expression))
        except ValueError as e:
            pass
    results = []
    for length, expression in inputs:
        result = calculate(expression)
        results.append(result)
    for result in results:
        print(result)

if __name__ == "__main__":
